#requires -Version 7.0
# Compile actual normal Capture, preparation wrapper, supervisor and wire with
# authored SDK + inert game/parser identities. No installed resource is read.
[CmdletBinding()]
param([ValidateSet('fresh','immutable-held','stale','disabled','cancelled','busy-cancelled','preserve-existing','invalid-existing-time','expired-cache-negative','native-camera-route')][string[]]$Scenarios=@('fresh','immutable-held','stale','disabled','cancelled','busy-cancelled','preserve-existing','invalid-existing-time','expired-cache-negative','native-camera-route'))
$ErrorActionPreference='Stop';$repo=Split-Path -Parent $PSScriptRoot;$root=Join-Path $repo ('.local/street01/initial-preparation-offer-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($root)|Out-Null
$sources=@(Get-ChildItem -LiteralPath (Join-Path $repo 'src/acoustics/host/Transport') -Filter '*.cs'|ForEach-Object FullName)
$sources+=@('src/acoustics/integration/WorldWarmupSupervisor.cs','src/acoustics/bridge/Rph/InstalledWorldWarmup.Rph.cs','src/acoustics/bridge/Rph/Playable.Rph.cs','src/acoustics/bridge/Rph/CameraSampler.Rph.cs','tests/host/TestInitialPreparationOffer01.cs')|ForEach-Object{Join-Path $repo $_}
$pins=@($sources|ForEach-Object{[ordered]@{path=$_;sha256=(Get-FileHash -LiteralPath $_).Hash.ToLowerInvariant()}});$binary=Join-Path $root 'GTA5_Enhanced.exe';$compiler=Join-Path $env:WINDIR 'Microsoft.NET/Framework64/v4.0.30319/csc.exe'
[ordered]@{schema=1;kind='RichAudioOriginalInitialPreparationAttempt01';scenarios=$Scenarios;sourcePins=$pins;runnerSHA256=(Get-FileHash -LiteralPath $PSCommandPath).Hash.ToLowerInvariant();compilerSHA256=(Get-FileHash -LiteralPath $compiler).Hash.ToLowerInvariant();compiledBytesUploaded=$false;installedResourcesRead=$false}|ConvertTo-Json -Depth 7|Set-Content -LiteralPath (Join-Path $root 'attempt.json') -Encoding utf8
$build=@(& $compiler /nologo /optimize+ /warnaserror+ /langversion:5 /platform:x64 /r:System.Runtime.Serialization.dll /r:Microsoft.CSharp.dll /r:System.Web.Extensions.dll /main:TestInitialPreparationOffer01 ('/out:'+$binary) @sources 2>&1);$build|Set-Content -LiteralPath (Join-Path $root 'build.log');if($LASTEXITCODE){throw ('Actual preparation offer fixture compilation failed; '+$root)}
$power=(Get-Process -Id $PID).Path;$results=@();foreach($scenario in $Scenarios){
 $case=Join-Path $root $scenario;$game=Join-Path $case 'game';[IO.Directory]::CreateDirectory($game)|Out-Null;Copy-Item -LiteralPath $binary -Destination $game
 $process=[Diagnostics.Process]::new();$process.StartInfo=[Diagnostics.ProcessStartInfo]@{FileName=(Join-Path $game 'GTA5_Enhanced.exe');Arguments=($scenario+' "'+$power+'"');WorkingDirectory=$case;UseShellExecute=$false;CreateNoWindow=$true;RedirectStandardOutput=$true;RedirectStandardError=$true};$null=$process.Start();$stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync();$closed=$process.WaitForExit(12000);if(!$closed){$process.Kill();$process.WaitForExit()};$stdout.Result|Set-Content -LiteralPath (Join-Path $case 'stdout.log');$stderr.Result|Set-Content -LiteralPath (Join-Path $case 'stderr.log');if(!$closed-or$process.ExitCode-ne0){
  [ordered]@{scenario=$scenario;childExited=$closed;exitCode=$process.ExitCode;sourcePins=$pins;installedResourcesRead=$false}|ConvertTo-Json -Depth 7|Set-Content -LiteralPath (Join-Path $case 'failure.json') -Encoding utf8
  foreach($name in @('stdout.log','stderr.log','failure-context.json')){if(Test-Path -LiteralPath (Join-Path $case $name)){$body=Get-Content -LiteralPath (Join-Path $case $name) -Raw;if($body.Length-gt12288){$body=$body.Substring($body.Length-12288)};Write-Output ('Original fixture failure '+$name+': '+$body)}}
  $process.Dispose();throw ('Actual initial preparation offer failed/timeout; '+$case)
 };$results+=$stdout.Result.Trim()|ConvertFrom-Json;$process.Dispose()
}
foreach($pin in $pins){if((Get-FileHash -LiteralPath $pin.path).Hash.ToLowerInvariant()-cne$pin.sha256){throw 'Preparation offer source changed during fixture'}}
[ordered]@{schema=1;passed=$true;kind='RichAudioActualCaptureBackgroundInitialPreparationOffer01';cases=$results;sourcePins=$pins;actualNormalCapture=$true;actualWarmupWrapperAndSupervisor=$true;authoredSdkResponses=$true;noAudioHost=$true;installedResourcesRead=$false;gameLaunched=$false;endpointOpened=$false}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $root 'validation.json') -Encoding utf8
Write-Output ('PASS '+$results.Count+' actual preparation-only Capture/background-writer scenarios; '+(Join-Path $root 'validation.json'))
